(function ($) {
  $.extend(true, gmwp.conf.cmp, {
    qf_cancel_reservation: {
      name: 'qf_cancel_reservation',
      requestButtonSelector: '.q-mod-cancel-reservation-button',
      agreementCheckboxSelector: '.q-mod-cancel-reservation-checkbox',
      dataTransformedLink: 'transformed-link'
    }
  });

  /**
   * [initElements description]
   */
  gmwp.mod.qf_cancel_reservation = gmwp.mod.AtomicMod.extend({
    /*************************************
     * METHODS EXTENDED FROM AtomicMod
     *************************************/
    initElements: function initElements() {
      var $ctx = this.$ctx,
        data = {};
      this.$requestButtonSelector = $ctx.find(this.cfg.requestButtonSelector);
      this.$agreementCheckboxSelector = $ctx.find(this.cfg.agreementCheckboxSelector);
      this.thankYouUrl = $ctx.data(this.cfg.dataTransformedLink);
    },
    prepare: function prepare() {
      gmwp.util.debugModule(this);
    },
    finish: function finish() {
      var $ctx = this.$ctx,
        self = this;
      $ctx.on('click.cancel', this.cfg.requestButtonSelector, $.proxy(this.cancelClick, this));
      $ctx.on('click.checkbox', this.cfg.agreementCheckboxSelector, $.proxy(this.checkboxClicked, this));
      addEventListener('twoFactorValid', function (data) {
        self.handleData(data.detail);
      });
    },
    setHeaders: function setHeaders(request) {
      request.setRequestHeader('clientApplicationId', 'quantum');
    },
    handleData: function handleData(data) {
      var self = this;
      if (data && data.reservationDetails[0] && data.reservationDetails[0].allowedActions.cancelAllowed) {
        self.data = data;
        $('.qf-cancel-reservation').show();
      }
    },
    checkboxClicked: function checkboxClicked() {
      if (this.$agreementCheckboxSelector.prop('checked') === true) {
        $('.q-mod-cancel-reservation-button').removeAttr('disabled');
        $('.q-mod-cancel-reservation-checkbox').addClass('checked');
      } else {
        $('.q-mod-cancel-reservation-button').attr('disabled', true);
        $('.q-mod-cancel-reservation-checkbox').removeClass('checked');
      }
    },
    cancelClick: function cancelClick() {
      var self = this;
      $('.q-mod-cancel-reservation-button').attr('disabled', true);
      $('.qf-cancel-reservation-service-error').css('display', 'none');
      var endPoint = '/bypass/pcf/routeone/cancelReservation';
      var serviceData = {
        requestType: 'cancel',
        gmCustomer: {
          email: this.data.reservationDetails[0].individualPartyDetails[0].partyEmails[0].email
        },
        orderId: this.data.reservationDetails[0].reservationOrderId
      };
      $.ajax({
        url: endPoint,
        headers: {
          'Content-Type': 'application/json',
          'clientApplicationId': 'quantum',
          'twoFAToken': self.data.twoFASessionToken
        },
        data: JSON.stringify(serviceData),
        method: 'POST',
        statusCode: {
          404: $.proxy(this.serviceError, this),
          400: $.proxy(this.serviceError, this),
          500: $.proxy(this.serviceError, this)
        },
        beforeSend: $.proxy(this.setHeaders, this),
        success: $.proxy(this.serviceSuccess, this),
        fail: $.proxy(this.serviceError, this)
      });
    },
    serviceSuccess: function serviceSuccess(data) {
      if (data.status !== 'success') {
        this.serviceError();
      } else {
        top.window.location.href = this.thankYouUrl;
      }
    },
    serviceError: function serviceError() {
      $('.q-mod-cancel-reservation-button').removeAttr('disabled');
      $('.qf-cancel-reservation-service-error').css('display', 'block');
    }
  });
})(gmwp.$);
