(function ($) {
  $.extend(true, gmwp.conf.cmp, {
    qf_change_dealer_reservation_info: {
      name: 'qf_change_dealer_reservation_info',
      dataNoReservationInfoModalHeadline: 'no-reservation-info-modal-headline',
      dataNoReservationInfoModalText: 'no-reservation-info-modal-text',
      dataEndpointSelection: 'endpoint-selection'
    }
  });

  /**
   * [initElements description]
   */
  gmwp.mod.qf_change_dealer_reservation_info = gmwp.mod.AtomicMod.extend({
    /*************************************
     * METHODS EXTENDED FROM AtomicMod
     *************************************/
    initElements: function initElements() {
      var $ctx = this.$ctx;
      this.noReservationInfoModalHeadline = $ctx.data(this.cfg.dataNoReservationInfoModalHeadline);
      this.noReservationInfoModalText = $ctx.data(this.cfg.dataNoReservationInfoModalText);
      this.endpointSelection = $ctx.data(this.cfg.dataEndpointSelection);
    },
    prepare: function prepare() {
      gmwp.util.debugModule(this);
    },
    finish: function finish() {
      var self = this;
      this.getReservationInfo();
      var sessionData = JSON.parse(sessionStorage.getItem('qf-change-dealer'));
      var gb = window.guideBridge;
      if (gb) {
        var orderId = gb.resolveNode('orderId');
        if (orderId) {
          orderId.value = JSON.stringify(sessionData.orderId);
        }
        var email = gb.resolveNode('email');
        if (email) {
          email.value = JSON.stringify(sessionData.email);
        }
        var isUnreferenced = gb.resolveNode('isUnreferenced');
        if (isUnreferenced) {
          isUnreferenced.value = JSON.stringify(sessionData.isUnreferenced);
        }

        //listener for populating info from inputted values
        addEventListener('populateUserInfoFromReservation', function () {
          self.populateChangeDealerInfo();
        });
      }
    },
    getReservationInfo: function getReservationInfo() {
      if (window.sessionStorage) {
        var self = this,
          sessionData = JSON.parse(sessionStorage.getItem('qf-change-dealer'));
        var endpoint,
          requestData = {
            orderId: sessionData.orderId,
            gmCustomer: {
              email: sessionData.email
            }
          };
        endpoint = this.endpointSelection ? this.endpointSelection : '/bypass/pcf/routeone/reservationDetail/orderDetails';
        $.ajax({
          url: endpoint,
          dataType: 'json',
          contentType: 'application/json',
          data: JSON.stringify(requestData),
          method: 'POST',
          headers: {
            clientApplicationId: 'quantum',
            twoFAToken: sessionData.twoFAToken
          },
          success: $.proxy(self.handleGetReservationInfo, this),
          error: $.proxy(self.handleChangeDealerError, this)
        });
      }
    },
    handleGetReservationInfo: function handleGetReservationInfo(data) {
      var self = this;
      if (data.status === 'success') {
        self.shortCodeMap = {
          'first-name': data.reservationDetails[0].individualPartyDetails[0].firstName,
          'last-name': data.reservationDetails[0].individualPartyDetails[0].lastName,
          'address-1': data.reservationDetails[0].individualPartyDetails[0].partyAddresses[0].addressLine01,
          'address-2': data.reservationDetails[0].individualPartyDetails[0].partyAddresses[0].addressLine02,
          city: data.reservationDetails[0].individualPartyDetails[0].partyAddresses[0].city,
          state: data.reservationDetails[0].individualPartyDetails[0].partyAddresses[0].stateCode,
          'zip-code': data.reservationDetails[0].individualPartyDetails[0].partyAddresses[0].postalCode,
          'phone-number': data.reservationDetails[0].individualPartyDetails[0].partyPhones[0].phone.replace(/(\d{3})(\d{3})(\d{4})/, '($1) $2-$3'),
          email: data.reservationDetails[0].individualPartyDetails[0].partyEmails[0].email
        };
        self.populateChangeDealerInfo();
      } else if (data.messages[0].description === '2FA sessionToken has expired') {
        sessionStorage.setItem('qf-change-dealer', JSON.stringify({
          timeout: true
        }));
        window.history.back();
      } else {
        this.handleChangeDealerError();
      }
    },
    populateChangeDealerInfo: function populateChangeDealerInfo() {
      // populating customer info from reservation
      var self = this,
        shortCodesList = ['first-name', 'last-name', 'address-1', 'address-2', 'city', 'state', 'zip-code', 'phone-number', 'email'];
      shortCodesList.forEach(function (shortCode) {
        var shortCodeSelector = '[data-shortcode-replacement="qfsc-' + shortCode + '"]',
          replacementSpans = document.querySelectorAll(shortCodeSelector);
        replacementSpans.forEach(function (el) {
          switch (shortCode) {
            case 'address-2':
              if (self.shortCodeMap[shortCode] && self.shortCodeMap[shortCode] !== 'N/A') {
                el.innerHTML = "<br/> ".concat(self.shortCodeMap[shortCode]);
              }
              break;
            default:
              if (self.shortCodeMap[shortCode]) {
                el.innerHTML = self.shortCodeMap[shortCode];
              }
              break;
          }
        });
      });
    },
    handleChangeDealerError: function handleChangeDealerError() {
      var self = this;
      var popNoInfoModal = new CustomEvent('popModal', {
        detail: {
          headline: self.noReservationInfoModalHeadline,
          body: self.noReservationInfoModalText,
          hideClose: true
        }
      });
      dispatchEvent(popNoInfoModal);
    }
  });
})(gmwp.$);
;
