(function ($) {
  $.extend(true, gmwp.conf.cmp, {
    qf_early_access_code: {
      name: 'qf_early_access_code',
      textSelector: '.q-text',
      dataInvalidCodeModalTitle: 'invalid-code-modal-title',
      dataInvalidCodeModalText: 'invalid-code-modal-text',
      dataBurntCodeModalTitle: 'burnt-code-modal-title',
      dataBurntCodeModalText: 'burnt-code-modal-text',
      dataTechnicalIssueModalTitle: 'technical-issue-modal-title',
      dataTechnicalIssueModalText: 'technical-issue-modal-text'
    }
  });

  /**
   * [initElements description]
   */
  gmwp.mod.qf_early_access_code = gmwp.mod.AtomicMod.extend({
    /*************************************
     * METHODS EXTENDED FROM AtomicMod
     *************************************/
    initElements: function initElements() {
      var $ctx = this.$ctx,
        queryParams = window.parent.gmwp.util.getQueryParams();
      this.invalidCodeModalTitle = $ctx.data(this.cfg.dataInvalidCodeModalTitle);
      this.invalidCodeModalText = $ctx.data(this.cfg.dataInvalidCodeModalText);
      this.burntCodeModalTitle = $ctx.data(this.cfg.dataBurntCodeModalTitle);
      this.burntCodeModalText = $ctx.data(this.cfg.dataBurntCodeModalText);
      this.technicalIssueModalTitle = $ctx.data(this.cfg.dataTechnicalIssueModalTitle);
      this.technicalIssueModalText = $ctx.data(this.cfg.dataTechnicalIssueModalText);
      if (queryParams) {
        this.eac = queryParams['eac'] || '';
      }
    },
    prepare: function prepare() {
      gmwp.util.debugModule(this);
    },
    finish: function finish() {
      var self = this;

      //set component value to code from query params
      var gb = window.guideBridge;
      if (gb) {
        var eacComponent = gb.resolveNode('earlyAccessCode');
        if (eacComponent) {
          eacComponent.value = this.eac;
        }
      }
      this.checkEAC();
    },
    checkEAC: function checkEAC() {
      var self = this,
        requestBody = {
          'accessCode': this.eac
        };
      $.ajax({
        type: 'POST',
        url: '/bypass/pcf/routeone/v2/validateAccessCode',
        headers: {
          'Content-Type': 'application/json',
          'clientApplicationId': 'quantum'
        },
        data: JSON.stringify(requestBody),
        dataType: 'json',
        success: function success(result) {
          if (result.status !== 'Valid') {
            if (result.status === 'Invalid') {
              var popEACInvalidModal = new CustomEvent('popModal', {
                detail: {
                  headline: self.invalidCodeModalTitle,
                  body: self.invalidCodeModalText,
                  hideClose: true
                }
              });
              dispatchEvent(popEACInvalidModal);
            } else if (result.status === 'Burnt') {
              var popEACBurntModal = new CustomEvent('popModal', {
                detail: {
                  headline: self.burntCodeModalTitle,
                  body: self.burntCodeModalText,
                  hideClose: true
                }
              });
              dispatchEvent(popEACBurntModal);
            } else {
              self.eacCheckFail();
            }
          }
        },
        statusCode: {
          404: function _() {
            $.proxy(self.eacCheckFail, self);
          },
          403: function _() {
            $.proxy(self.eacCheckFail, self);
          },
          400: function _() {
            $.proxy(self.eacCheckFail, self);
          },
          500: function _() {
            $.proxy(self.eacCheckFail, self);
          },
          503: function _() {
            $.proxy(self.eacCheckFail, self);
          }
        },
        fail: $.proxy(self.eacCheckFail, self)
      });
    },
    eacCheckFail: function eacCheckFail(data) {
      var self = this;
      var popEACTechModal = new CustomEvent('popModal', {
        detail: {
          headline: self.technicalIssueModalTitle,
          body: self.technicalIssueModalText,
          hideClose: true
        }
      });
      dispatchEvent(popEACTechModal);
    }
  });
})(gmwp.$);
;
