      dataGoogleMapsApiClientId: 'google-maps-client-id',
      dataGoogleMapsKey: 'google-maps-key',
      dataGoogleMapsApiUrl: 'google-maps-api-url',
      dataCityError: 'city-error',
      dataDealerError: 'dealer-error',
      dataNoCarManagersError: 'no-car-managers-error',
      dataNoRecommendedManagersError: 'n-recommended-managers-error',
